//! Purpose:
//! Generated Rust tests for the committed PHP 8.5.10 `ext/intl` PHPT corpus.
//!
//! Called from:
//! - `cargo test` through `tests/codegen/intl_php_src.rs`.
//!
//! Key details:
//! - Generated by `scripts/gen_php_src_intl_cases.py`; do not hand-edit.
//! - Each test carries its PHP source and assertion inline, and the test process
//!   never parses a `.phpt` file at run time.
//! - Tests php-src skips on this platform are preserved as ignored cases with the
//!   original skip reason, so the provenance stays complete.

#![allow(non_snake_case)]

use super::{assert_format, assert_regex, run_case};

/// Replays php-src `IntlIterator_cycle_management.phpt`.
#[test]
fn test_php_src_intl_IntlIterator_cycle_management() {
    let out = run_case("<?php\nfunction break_cycle_test() {\n\t$obj = IntlCalendar::getKeywordValuesForLocale('calendar', 'fa_IR', true);\n\tunset($obj);\n\tvar_dump(gc_collect_cycles());\n}\nbreak_cycle_test();\nbreak_cycle_test();\nbreak_cycle_test();\n", "", &[], &[]);
    assert_eq!(out, "int(1)\nint(1)\nint(1)");
}

/// Replays php-src `badargs.phpt`.
#[test]
fn test_php_src_intl_badargs() {
    let out = run_case("<?php\n$funcs = get_extension_funcs(\"intl\");\nfunction ignore_err() {}\nset_error_handler(\"ignore_err\");\n$arg = new stdClass();\nforeach($funcs as $func) {\n        $rfunc = new ReflectionFunction($func);\n        if($rfunc->getNumberOfRequiredParameters() == 0) {\n                continue;\n        }\n\n        try {\n            $res = $func($arg);\n        } catch (Exception $e) {\n            continue;\n        } catch (Error $e) {\n            continue;\n        }\n        if($res != false) {\n                echo \"$func: \";\n                var_dump($res);\n        }\n}\necho \"OK!\\n\";\n", "", &[], &[]);
    assert_eq!(out, "OK!");
}

/// Replays php-src `breakiter___construct.phpt`.
#[test]
fn test_php_src_intl_breakiter___construct() {
    let out = run_case("<?php\n\ntry {\n\tnew IntlBreakIterator();\n} catch (Throwable $e) {\n\techo $e::class, ': ', $e->getMessage(), PHP_EOL;\n}\n", "", &[], &[]);
    assert_eq!(out, "Error: Call to private IntlBreakIterator::__construct() from global scope");
}

/// Replays php-src `breakiter___construct_error.phpt`.
#[test]
fn test_php_src_intl_breakiter___construct_error() {
    let out = run_case("<?php\n\n//missing ; at the end:\ntry {\n    var_dump(new IntlRuleBasedBreakIterator('[\\p{Letter}\\uFFFD]+;[:number:]+'));\n} catch (Throwable $e) {\n\techo $e::class, ': ', $e->getMessage(), PHP_EOL;\n}\ntry {\n    var_dump(new IntlRuleBasedBreakIterator());\n} catch (Throwable $e) {\n\techo $e::class, ': ', $e->getMessage(), PHP_EOL;\n}\ntry {\n    var_dump(new IntlRuleBasedBreakIterator(1,2,3));\n} catch (Throwable $e) {\n\techo $e::class, ': ', $e->getMessage(), PHP_EOL;\n}\ntry {\n    var_dump(new IntlRuleBasedBreakIterator('[\\p{Letter}\\uFFFD]+;[:number:]+;', array()));\n} catch (Throwable $e) {\n\techo $e::class, ': ', $e->getMessage(), PHP_EOL;\n}\ntry {\n    var_dump(new IntlRuleBasedBreakIterator('[\\p{Letter}\\uFFFD]+;[:number:]+;', true));\n} catch (Throwable $e) {\n\techo $e::class, ': ', $e->getMessage(), PHP_EOL;\n}\n\n$rbbi = new IntlRuleBasedBreakIterator(\".;\");\ntry {\n    $rbbi->__construct(\".;\");\n} catch (Throwable $e) {\n\techo $e::class, ': ', $e->getMessage(), PHP_EOL;\n}\n", "", &[], &[]);
    assert_eq!(out, "IntlException: IntlRuleBasedBreakIterator::__construct(): unable to create RuleBasedBreakIterator from rules (parse error on line 1, offset 31)\nArgumentCountError: IntlRuleBasedBreakIterator::__construct() expects at least 1 argument, 0 given\nArgumentCountError: IntlRuleBasedBreakIterator::__construct() expects at most 2 arguments, 3 given\nTypeError: IntlRuleBasedBreakIterator::__construct(): Argument #2 ($compiled) must be of type bool, array given\nIntlException: IntlRuleBasedBreakIterator::__construct(): unable to create instance from compiled rules\nError: IntlRuleBasedBreakIterator object is already constructed");
}

