/// Replays php-src `cpbi_getLastCodePoint_basic.phpt`.
#[test]
fn test_php_src_intl_cpbi_getLastCodePoint_basic() {
    let out = run_case("<?php\n\n$text = 'ตัวอย่างข้อความ';\n\n$codepoint_it = IntlBreakIterator::createCodePointInstance();\n$codepoint_it->setText($text);\n\nvar_dump($codepoint_it->getLastCodePoint());\n//first() and last() don't read codepoint and set the last code point var to -1\n//The pointer is after the last read codepoint if moving forward and\n//before the last read codepoint is moving backwards\n$p = $codepoint_it->first();\nwhile ($p != IntlBreakIterator::DONE) {\n    $c = $codepoint_it->getLastCodePoint();\n    if ($c > 0)\n        var_dump(sprintf('U+%04X', $codepoint_it->getLastCodePoint()));\n    else\n        var_dump($c);\n    //it's a post-increment operation as to the codepoint, i.e., it gives the codepoint\n    //starting at the initial position and only then moves the pointer forward\n    $p = $codepoint_it->next();\n}\n\necho \"Now backwards\\n\";\n$p = $codepoint_it->last();\nwhile ($p != IntlBreakIterator::DONE) {\n    $c = $codepoint_it->getLastCodePoint();\n    if ($c > 0)\n        var_dump(sprintf('U+%04X', $codepoint_it->getLastCodePoint()));\n    else\n        var_dump($c);\n    $p = $codepoint_it->previous();\n}\n\n\n", "", &[(r#"intl.default_locale"#, r#"pt_PT"#)], &[]);
    assert_eq!(out, "int(-1)\nint(-1)\nstring(6) \"U+0E15\"\nstring(6) \"U+0E31\"\nstring(6) \"U+0E27\"\nstring(6) \"U+0E2D\"\nstring(6) \"U+0E22\"\nstring(6) \"U+0E48\"\nstring(6) \"U+0E32\"\nstring(6) \"U+0E07\"\nstring(6) \"U+0E02\"\nstring(6) \"U+0E49\"\nstring(6) \"U+0E2D\"\nstring(6) \"U+0E04\"\nstring(6) \"U+0E27\"\nstring(6) \"U+0E32\"\nstring(6) \"U+0E21\"\nNow backwards\nint(-1)\nstring(6) \"U+0E21\"\nstring(6) \"U+0E32\"\nstring(6) \"U+0E27\"\nstring(6) \"U+0E04\"\nstring(6) \"U+0E2D\"\nstring(6) \"U+0E49\"\nstring(6) \"U+0E02\"\nstring(6) \"U+0E07\"\nstring(6) \"U+0E32\"\nstring(6) \"U+0E48\"\nstring(6) \"U+0E22\"\nstring(6) \"U+0E2D\"\nstring(6) \"U+0E27\"\nstring(6) \"U+0E31\"\nstring(6) \"U+0E15\"");
}

