/// Replays php-src `dateformat_get_datetype.phpt`.
#[test]
fn test_php_src_intl_dateformat_get_datetype() {
    let out = run_case("<?php\n\n/*\n * Test for the datefmt_get_datetype  function\n */\n\n\nfunction ut_main()\n{\n    $datetype_arr = array (\n        IntlDateFormatter::FULL,\n        IntlDateFormatter::LONG,\n        IntlDateFormatter::MEDIUM,\n        IntlDateFormatter::SHORT,\n        IntlDateFormatter::NONE\n    );\n\n    $res_str = '';\n\n    foreach( $datetype_arr as $datetype_entry )\n    {\n        $res_str .= \"\\nCreating IntlDateFormatter with date_type = $datetype_entry\";\n        $fmt = ut_datefmt_create( \"de-DE\",  $datetype_entry , IntlDateFormatter::SHORT,'America/Los_Angeles', IntlDateFormatter::GREGORIAN  );\n        $date_type = ut_datefmt_get_datetype( $fmt);\n        $res_str .= \"\\nAfter call to get_datetype :  datetype= $date_type\";\n        $res_str .= \"\\n\";\n    }\n\n    return $res_str;\n\n}\n\ninclude_once( 'ut_common.inc' );\n\n// Run the test\nut_run();\n", "", &[], &[]);
    assert_eq!(out, "Creating IntlDateFormatter with date_type = 0\nAfter call to get_datetype :  datetype= 0\n\nCreating IntlDateFormatter with date_type = 1\nAfter call to get_datetype :  datetype= 1\n\nCreating IntlDateFormatter with date_type = 2\nAfter call to get_datetype :  datetype= 2\n\nCreating IntlDateFormatter with date_type = 3\nAfter call to get_datetype :  datetype= 3\n\nCreating IntlDateFormatter with date_type = -1\nAfter call to get_datetype :  datetype= -1");
}

/// Replays php-src `dateformat_get_locale.phpt`.
#[test]
fn test_php_src_intl_dateformat_get_locale() {
    let out = run_case("<?php\n\n/*\n * Test for the datefmt_get_locale  function\n */\n\n\nfunction ut_main()\n{\n    $locale_arr = array (\n        'de-DE',\n        'sl-IT-nedis',\n        'en_UK',\n        'hi'\n    );\n\n    $res_str = '';\n\n    foreach( $locale_arr as $locale_entry )\n    {\n        $res_str .= \"\\nCreating IntlDateFormatter with locale = $locale_entry\";\n        $fmt = ut_datefmt_create( $locale_entry , IntlDateFormatter::SHORT,IntlDateFormatter::SHORT,'America/Los_Angeles', IntlDateFormatter::GREGORIAN  );\n        $locale = ut_datefmt_get_locale( $fmt , 1);\n        $res_str .= \"\\nAfter call to get_locale :  locale= $locale\";\n        $res_str .= \"\\n\";\n    }\n    $badvals = array(100, -1, 4294901761);\n    foreach($badvals as $badval) {\n        if(ut_datefmt_get_locale($fmt, $badval)) {\n            $res_str .= \"datefmt_get_locale should return false for bad argument $badval\\n\";\n        }\n    }\n\n    return $res_str;\n\n}\n\ninclude_once( 'ut_common.inc' );\n\n// Run the test\nut_run();\n", "", &[], &[]);
    assert_eq!(out, "Creating IntlDateFormatter with locale = de-DE\nAfter call to get_locale :  locale= de_DE\n\nCreating IntlDateFormatter with locale = sl-IT-nedis\nAfter call to get_locale :  locale= sl\n\nCreating IntlDateFormatter with locale = en_UK\nAfter call to get_locale :  locale= en\n\nCreating IntlDateFormatter with locale = hi\nAfter call to get_locale :  locale= hi");
}

/// Replays php-src `dateformat_get_set_calendar_variant4.phpt`.
#[test]
    #[ignore = "php-src SKIP on this platform: for ICU < 58.1"]
fn test_php_src_intl_dateformat_get_set_calendar_variant4() {
    let out = run_case("<?php\n\n$ts = strtotime('2012-01-01 00:00:00 UTC');\n\nfunction d(IntlDateFormatter $df) {\nglobal $ts;\necho $df->format($ts), \"\\n\";\nvar_dump($df->getCalendar(),\n$df->getCalendarObject()->getType(),\n$df->getCalendarObject()->getTimeZone()->getId());\necho \"\\n\";\n}\n\n$df = new IntlDateFormatter('fr@calendar=islamic', 0, 0, 'Europe/Minsk');\nd($df);\n\n\n//changing the calendar with a cal type should not change tz\n$df->setCalendar(IntlDateFormatter::TRADITIONAL);\nd($df);\n\n//but changing with an actual calendar should\n$cal = IntlCalendar::createInstance(\"UTC\");\n$df->setCalendar($cal);\nd($df);\n\n", "", &[(r#"intl.default_locale"#, r#"pt_PT"#), (r#"date.timezone"#, r#"Atlantic/Azores"#)], &[]);
    assert_eq!(out, "dimanche 1 janvier 2012 ap. J.-C. à 03:00:00 heure de Kaliningrad\nint(1)\nstring(9) \"gregorian\"\nstring(12) \"Europe/Minsk\"\n\ndimanche 8 safar 1433 AH à 03:00:00 heure de Kaliningrad\nint(0)\nstring(7) \"islamic\"\nstring(12) \"Europe/Minsk\"\n\ndimanche 1 janvier 2012 ap. J.-C. à 00:00:00 UTC\nbool(false)\nstring(9) \"gregorian\"\nstring(3) \"UTC\"");
}

