/// Replays php-src `locale_compose_lookup_references.phpt`.
#[test]
fn test_php_src_intl_locale_compose_lookup_references() {
    let out = run_case("<?php\n\n$en = 'en';\n$data = [Locale::LANG_TAG => 'en', Locale::REGION_TAG => &$en];\n\nvar_dump(locale_compose($data));\n\n$data = [\n\t'language' => 'de', \n\t'script' => 'Hans',\n\t'region' => 'DE',\n\t'variant2' => 'fr',\n\t'variant1' => &$en,\n\t'private1' => 'private1',\n\t'private2' => 'private2',\n\t];\nvar_dump(locale_compose($data));\n$data = ['de', &$en];\nvar_dump(locale_lookup($data, \"en\", '', \"en\"));\n", "", &[], &[]);
    assert_eq!(out, "string(5) \"en_en\"\nstring(36) \"de_Hans_DE_en_fr_x_private1_private2\"\nstring(2) \"en\"");
}

