/// Replays php-src `locale_get_all_variants.phpt`.
#[test]
fn test_php_src_intl_locale_get_all_variants() {
    let out = run_case("<?php\n\n/*\n * Try parsing different Locales\n * with Procedural and Object methods.\n */\n\nfunction ut_main()\n{\n    $locales  = array(\n        'sl_IT_nedis_KIRTI',\n        'sl_IT_nedis-a-kirti-x-xyz',\n        'sl_IT_rozaj',\n        'sl_IT_NEDIS_ROJAZ_1901',\n        'i-enochian',\n        'zh-hakka',\n        'zh-wuu',\n        'i-tay',\n        'sgn-BE-nl',\n        'sgn-CH-de',\n        'sl_IT_rozaj@currency=EUR'\n    );\n    $res_str = '';\n    foreach($locales as $locale){\n        $variants_arr = ut_loc_locale_get_all_variants( $locale);\n        $res_str .= \"$locale : variants \";\n        if( $variants_arr){\n            foreach($variants_arr as $variant){\n                $res_str .= \"'$variant',\";\n            }\n        }else{\n            $res_str .= \"--none\";\n        }\n        $res_str .= \"\\n\";\n    }\n\n    try {\n\t    ut_loc_locale_get_all_variants(\"i-\\0tay\");\n    } catch (\\ValueError $e) {\n\t    echo $e->getMessage(). PHP_EOL;\n    }\n\n    $res_str .= \"\\n\";\n    return $res_str;\n\n}\n\ninclude_once( 'ut_common.inc' );\nut_run();\n\n", "", &[], &[]);
    assert_eq!(out, "Locale::getAllVariants(): Argument #1 ($locale) must not contain any null bytes\nlocale_get_all_variants(): Argument #1 ($locale) must not contain any null bytes\nsl_IT_nedis_KIRTI : variants 'NEDIS','KIRTI',\nsl_IT_nedis-a-kirti-x-xyz : variants 'NEDIS',\nsl_IT_rozaj : variants 'ROZAJ',\nsl_IT_NEDIS_ROJAZ_1901 : variants 'NEDIS','ROJAZ','1901',\ni-enochian : variants --none\nzh-hakka : variants --none\nzh-wuu : variants --none\ni-tay : variants --none\nsgn-BE-nl : variants --none\nsgn-CH-de : variants --none\nsl_IT_rozaj@currency=EUR : variants 'ROZAJ',");
}

/// Replays php-src `locale_get_default.phpt`.
#[test]
fn test_php_src_intl_locale_get_default() {
    let out = run_case("<?php\n\n/*\n * Try getting the default Locale with different locales\n * with Procedural and Object methods.\n */\n\nfunction ut_main()\n{\n    $res_str = '';\n\n    $lang = ut_loc_get_default() ;\n    $res_str .= \"Default locale: $lang\";\n    $res_str .= \"\\n\";\n\n    locale_set_default('de-DE');\n    $lang = ut_loc_get_default() ;\n    $res_str .= \"Default locale: $lang\";\n    $res_str .= \"\\n\";\n\n    locale_set_default('fr');\n    $lang = ut_loc_get_default() ;\n    $res_str .= \"Default locale: $lang\";\n    $res_str .= \"\\n\";\n\n    locale_set_default('');\n\n    return $res_str;\n\n}\n\ninclude_once( 'ut_common.inc' );\nut_run();\n\n", "", &[(r#"intl.default_locale"#, r#"en-US"#)], &[]);
    assert_eq!(out, "Default locale: en-US\nDefault locale: de-DE\nDefault locale: fr");
}

