/// Replays php-src `locale_is_right_to_left.phpt`.
#[test]
fn test_php_src_intl_locale_is_right_to_left() {
    let out = run_case("<?php\nvar_dump(Locale::isRightToLeft(\"en-US\"));\nvar_dump(Locale::isRightToLeft(\"\\INVALID\\\\\"));\nvar_dump(Locale::isRightToLeft(\"\"));\nvar_dump(Locale::isRightToLeft(\"ar\"));\ntry {\n\tLocale::isRightToLeft(\"a\\0r\");\n} catch (\\ValueError $e) {\n\techo $e->getMessage();\n}\n", "", &[], &[]);
    assert_eq!(out, "bool(false)\nbool(false)\nbool(false)\nbool(true)\nLocale::isRightToLeft(): Argument #1 ($locale) must not contain any null bytes");
}

/// Replays php-src `locale_lookup_invalid_language_tag.phpt`.
#[test]
fn test_php_src_intl_locale_lookup_invalid_language_tag() {
    let out = run_case("<?php\n\nvar_dump(Locale::lookup([''], 'de-DE', false, 'en-US'));\nvar_dump(intl_get_error_message());\n\nvar_dump(locale_lookup([''], 'de-DE', '', 'en-US'));\nvar_dump(intl_get_error_message());\n\nini_set('intl.use_exceptions', '1');\n\ntry {\n    Locale::lookup([''], 'de-DE', false, 'en-US');\n} catch (IntlException $e) {\n    echo $e->getMessage(), PHP_EOL;\n}\n\ntry {\n    locale_lookup([''], 'de-DE', '', 'en-US');\n} catch (IntlException $e) {\n    echo $e->getMessage(), PHP_EOL;\n}\n\n", "", &[], &[]);
    assert_eq!(out, "NULL\nstring(75) \"Locale::lookup(): unable to canonicalize lang_tag: U_ILLEGAL_ARGUMENT_ERROR\"\nNULL\nstring(74) \"locale_lookup(): unable to canonicalize lang_tag: U_ILLEGAL_ARGUMENT_ERROR\"\nLocale::lookup(): unable to canonicalize lang_tag\nlocale_lookup(): unable to canonicalize lang_tag");
}

