/// Replays php-src `locale_subtags.phpt`.
#[test]
fn test_php_src_intl_locale_subtags() {
    let out = run_case("<?php\n$locale = \"en\";\n$max = Locale::addLikelySubtags($locale);\n$min = Locale::minimizeSubtags($max);\nvar_dump($min === $locale);\nvar_dump($max !== $locale && strlen($max) > strlen($locale));\nvar_dump(Locale::addLikelySubtags($max) === $max);\nvar_dump(Locale::minimizeSubtags($locale) === $locale);\nvar_dump(Locale::addLikelySubtags(\"%%%invalid%%%locale%%%\"));\nvar_dump(intl_get_error_message());\nvar_dump(Locale::minimizeSubtags(\"%%%Invalid%%%maximized%%%locale%%%\"));\nvar_dump(intl_get_error_message());\nvar_dump(Locale::addLikelySubTags(str_repeat($locale, 1024)));\nvar_dump(intl_get_error_message());\nvar_dump(Locale::minimizeSubTags(str_repeat($max, 1024)));\nvar_dump(intl_get_error_message());\n", "", &[], &[]);
    assert_format(&out, "bool(true)\nbool(true)\nbool(true)\nbool(true)\nbool(false)\nstring(68) \"Locale::addLikelySubtags(): invalid locale: U_ILLEGAL_ARGUMENT_ERROR\"\nbool(false)\nstring(67) \"Locale::minimizeSubtags(): invalid locale: U_ILLEGAL_ARGUMENT_ERROR\"\nbool(false)\nstring(68) \"Locale::addLikelySubtags(): invalid locale: U_ILLEGAL_ARGUMENT_ERROR\"\nbool(false)\nstring(%d) \"Locale::minimizeSubtags(): invalid locale: %s\"");
}

/// Replays php-src `msgfmt_bug70484.phpt`.
#[test]
fn test_php_src_intl_msgfmt_bug70484() {
    let out = run_case("<?php\n\n$locale = array(\"de\", \"fr\", \"en\", \"ru\",);\n\n$data = array(42, 42.42, 2147483643, 2147483643.12345, 5);\n\nforeach ($locale as $lc) {\n    echo \"$lc string key\\n\";\n    $m = new MessageFormatter($lc, \"{n, selectordinal, =5 {five} zero {#-zero} one {#-one} two {#-two} few {#-few} many {#-many} other {#-other}}\");\n    foreach ($data as $i) {\n        var_dump($m->format(array(\"n\" => $i)));\n        if ($m->getErrorCode()) {\n            echo \"$lc $i \", $m->getErrorMessage();\n        }\n    }\n    echo \"\\n\";\n\n    echo \"$lc numeric key\\n\";\n    $m = new MessageFormatter($lc, \"{0, selectordinal, =5 {five} zero {#-zero} one {#-one} two {#-two} few {#-few} many {#-many} other {#-other}}\");\n    foreach ($data as $i) {\n        var_dump($m->format(array($i)));\n        if ($m->getErrorCode()) {\n            echo \"$lc $i \", $m->getErrorMessage();\n        }\n    }\n    echo \"\\n\";\n}\n\n", "", &[], &[]);
    assert_format(&out, "de string key\nstring(8) \"42-other\"\nstring(11) \"42,42-other\"\nstring(19) \"2.147.483.643-other\"\nstring(23) \"2.147.483.643,123-other\"\nstring(4) \"five\"\n\nde numeric key\nstring(8) \"42-other\"\nstring(11) \"42,42-other\"\nstring(19) \"2.147.483.643-other\"\nstring(23) \"2.147.483.643,123-other\"\nstring(4) \"five\"\n\nfr string key\nstring(8) \"42-other\"\nstring(11) \"42,42-other\"\nstring(%d) \"2%s147%s483%s643-other\"\nstring(%d) \"2%s147%s483%s643,123-other\"\nstring(4) \"five\"\n\nfr numeric key\nstring(8) \"42-other\"\nstring(11) \"42,42-other\"\nstring(%d) \"2%s147%s483%s643-other\"\nstring(%d) \"2%s147%s483%s643,123-other\"\nstring(4) \"five\"\n\nen string key\nstring(6) \"42-two\"\nstring(11) \"42.42-other\"\nstring(17) \"2,147,483,643-few\"\nstring(23) \"2,147,483,643.123-other\"\nstring(4) \"five\"\n\nen numeric key\nstring(6) \"42-two\"\nstring(11) \"42.42-other\"\nstring(17) \"2,147,483,643-few\"\nstring(23) \"2,147,483,643.123-other\"\nstring(4) \"five\"\n\nru string key\nstring(8) \"42-other\"\nstring(11) \"42,42-other\"\nstring(22) \"2 147 483 643-other\"\nstring(26) \"2 147 483 643,123-other\"\nstring(4) \"five\"\n\nru numeric key\nstring(8) \"42-other\"\nstring(11) \"42,42-other\"\nstring(22) \"2 147 483 643-other\"\nstring(26) \"2 147 483 643,123-other\"\nstring(4) \"five\"");
}

/// Replays php-src `msgfmt_clone.phpt`.
#[test]
fn test_php_src_intl_msgfmt_clone() {
    let out = run_case("<?php\ninclude_once( 'ut_common.inc' );\n$GLOBALS['oo-mode'] = true;\n$res_str = '';\n/*\n * Clone\n */\n$fmt = ut_msgfmt_create( \"en_US\", \"{0,number} monkeys on {1,number} trees\" );\n\n// Get default patten.\n$res_str .= \"Formatting result: \" . ut_msgfmt_format( $fmt, array(123, 456) ) . \"\\n\";\n$fmt_clone = clone $fmt;\n// Set a new pattern.\n$pattern = \"{0,number} trees hosting {1,number} monkeys\";\n$res = ut_msgfmt_set_pattern( $fmt, $pattern );\n$res_str .= \"Formatting result: \" . ut_msgfmt_format( $fmt, array(123, 456) ) . \"\\n\";\n$res_str .= \"Formatting clone result: \" . ut_msgfmt_format( $fmt_clone, array(123, 456) ) . \"\\n\";\n\necho $res_str;\n\n", "", &[], &[]);
    assert_eq!(out, "Formatting result: 123 monkeys on 456 trees\nFormatting result: 123 trees hosting 456 monkeys\nFormatting clone result: 123 monkeys on 456 trees");
}

