/// Replays php-src `numfmt_parse_currency_references.phpt`.
#[test]
fn test_php_src_intl_numfmt_parse_currency_references() {
    let out = run_case("<?php\nclass Test {\n    public int $prop = 1;\n}\n$test = new Test;\n$fmt = numfmt_create( 'de_DE', NumberFormatter::CURRENCY );\n$num = \"1\\xc2\\xa0$\";\ntry {\n    numfmt_parse_currency($fmt, $num, $test->prop);\n} catch (TypeError $e) {\n    echo $e->getMessage(), \"\\n\";\n}\n", "", &[], &[]);
    assert_eq!(out, "Cannot assign string to reference held by property Test::$prop of type int");
}

